/* runtime.c — the Heroes C runtime (design.md §4.20).
 *
 * Per-type functions are generated by the COMPILER, not written here (§4.20):
 * C has no copy constructors or generic comparison, and a type-erased `void*`
 * runtime would void the "clang type-checks every call" property. So this whole
 * directory holds only what the language cannot express.
 *
 * ONE TRANSLATION UNIT, ELEVEN FILES, and the arrangement is deliberate.
 *
 * The runtime passed 1200 lines at M-generics-library step 3, four times CLAUDE.md §11's ceiling
 * — "the author must be able to open any file and read it without drowning".
 * `runtime/parts/` is that file split by concern, and this file includes them in
 * dependency order so the result is still exactly one translation unit.
 *
 * Why not eleven translation units, which is what a C programmer expects:
 *
 *   - `hero_live_blocks` is `static`, and it is the leak gate's whole
 *     foundation (panel 021: ASan has no leak detector on Darwin arm64, so this
 *     counter is the instrument). Across TUs it would have to become an extern
 *     global, reachable by anything linked in — including a decoy runtime.
 *   - Every helper here is `static` for the same reason: `hero_str_alloc`,
 *     `hero_array_data`, `hero_map_slot_of` are invariant-carrying and belong to
 *     nobody outside. Splitting into TUs promotes all of them to public symbols
 *     and turns an internal contract into an ABI.
 *   - `Toolchain::runtime_object` compiles the runtime to ONE `.o` and caches it
 *     (`crates/heroes-cli/src/commands/toolchain.rs`). Eleven objects would need
 *     an archive or `ld -r`, which is build machinery CLAUDE.md §10 does not
 *     want and this project does not need.
 *
 * The cost is one rule, and it is the one a reader has to know: **the include
 * order below IS the dependency order**, so a part may use anything the parts
 * above it define and nothing from below. Where that is not obvious the part
 * says so in its own header.
 *
 * The cache key hashes every file in this directory, not just this one — a part
 * edited without touching `runtime.c` must still invalidate the cached object,
 * and a stale relink is silent.
 */

#include "heroes_runtime.h"

#include <locale.h>
#include <float.h>
#include <math.h>
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <xlocale.h>

/* Aborting and printing: no dependencies, and everything below may abort. */
#include "parts/panic.c"

/* `str`, the reference counting, and the live-block counter that all three
 * containers below increment. */
#include "parts/str.c"

/* Canonical `f64` rendering and the three `to_str` conversions — `str`'s
 * allocator is what they build on. */
#include "parts/f64.c"

/* The four scalar descriptors. They reference `str`'s incref/decref. */
#include "parts/desc.c"

/* `[T]`, its descriptor, and the primitives that do not mutate. */
#include "parts/array.c"

/* `sort`, which needs the array's layout helpers and the scalar descriptors it
 * dispatches on by pointer identity. */
#include "parts/sort.c"

/* Where `str` and `[T]` meet: `chars` and `join`. Needs both. */
#include "parts/text.c"

/* Copy-on-write: the array primitives that DO mutate, kept apart from the ones
 * that do not, because the unshare rule is the subtlest thing in this runtime. */
#include "parts/cow.c"

/* The failure side of `T?`, and `.must()`'s abort. */
#include "parts/failure.c"

/* `{K: V}`: the representation and everything that reads it. */
#include "parts/map.c"

/* The map's descriptor and everything that writes: `keys`, growth, the unshare
 * the map shipped without, and the place store. Needs `[T]` for `keys`. */
#include "parts/map-write.c"
